const char* port_mod_msg_suffix(unsigned int msgID) {
    unsigned int section = msgID >> 16;
    unsigned int index = msgID & 0xFFFF;

    if (section >= 47 || index >= sSections[section].count) {
        return 0;
    }
    return sSections[section].names[index];
}
